#[inline]
pub fn tx_has_cross_slot(tx_queue: &[Command]) -> bool {
    let mut expected_slot: Option<u16> = None;
    for cmd in tx_queue {
        for k in cmd_keys(cmd) {
            let slot = crate::router::key_slot(k);
            if let Some(s) = expected_slot {
                if s != slot {
                    return true;
                }
            } else {
                expected_slot = Some(slot);
            }
        }
    }
    false
}

