#[inline]
pub fn record_cmd_stat(name: &'static str) {
    record_cmd_stats(name, 1, 0);
}

/// Adds `calls` calls of `name` taking `nanos` in total to this thread's
/// command statistics.
pub fn record_cmd_stats(name: &'static str, calls: u64, nanos: u64) {
    crate::server_stats::add(crate::server_stats::Stat::Commands, calls);
    LOCAL_CMD_STATS.with(|stats| {
        let mut map = stats.borrow_mut();
        map.entry(name).or_default().add(calls, nanos);
    });
    LOCAL_CMD_COUNT.with(|count| {
        let c = count.get() + calls as usize;
        if c >= 1024 {
            count.set(0);
            flush_local_cmd_stats();
        } else {
            count.set(c);
        }
    });
}

/// Commands whose run time includes waiting for data, replicas or fsync.
/// Like Redis, the wait is not counted as execution time.
fn may_block(cmd: &Command) -> bool {
    matches!(
        cmd,
        Command::Blpop { .. }
            | Command::Brpop { .. }
            | Command::Blmpop { .. }
            | Command::Blmove { .. }
            | Command::Bzpopmin { .. }
            | Command::Bzpopmax { .. }
            | Command::Bzmpop { .. }
            | Command::Xread { .. }
            | Command::Xreadgroup { .. }
            | Command::Wait { .. }
            | Command::WaitAof { .. }
    )
}

/// Records one call of a command run by `execute_command`, timed from
/// `start` until the guard drops.
struct CmdStatGuard {
    name: &'static str,
    start: Option<std::time::Instant>,
}

impl Drop for CmdStatGuard {
    fn drop(&mut self) {
        let nanos = self.start.map_or(0, |s| s.elapsed().as_nanos() as u64);
        record_cmd_stats(self.name, 1, nanos);
    }
}

/// Command statistics for one batched pipeline. Calls are tallied per
/// command name; the time of each segment (the stretch between `restart`
/// and `flush`) is split across the commands counted in it in proportion
/// to their calls. That costs two clock reads per segment instead of two
/// per command.
struct CmdStatBatch {
    start: std::time::Instant,
    runs: smallvec::SmallVec<[(&'static str, u64); 8]>,
}

impl CmdStatBatch {
    fn new() -> Self {
        Self {
            start: std::time::Instant::now(),
            runs: smallvec::SmallVec::new(),
        }
    }

    #[inline]
    fn note(&mut self, name: &'static str) {
        if let Some(last) = self.runs.last_mut()
            && std::ptr::eq(last.0, name)
        {
            last.1 += 1;
        } else if let Some(run) = self.runs.iter_mut().find(|r| std::ptr::eq(r.0, name)) {
            run.1 += 1;
        } else {
            self.runs.push((name, 1));
        }
    }

    /// Ends the current segment and records its commands.
    fn flush(&mut self) {
        if self.runs.is_empty() {
            return;
        }
        let elapsed = self.start.elapsed().as_nanos();
        let total: u64 = self.runs.iter().map(|r| r.1).sum();
        for (name, calls) in self.runs.drain(..) {
            let nanos = elapsed * u128::from(calls) / u128::from(total);
            record_cmd_stats(name, calls, nanos as u64);
        }
    }

    /// Starts a new segment, leaving out the time since the last `flush`.
    fn restart(&mut self) {
        self.start = std::time::Instant::now();
    }
}

pub fn flush_local_cmd_stats() {
    LOCAL_CMD_STATS.with(|stats| {
        let mut local_map = stats.borrow_mut();
        if local_map.is_empty() {
            return;
        }
        if let Ok(mut global_map) = CMD_STATS.write() {
            for (&cmd, stat) in local_map.iter() {
                global_map
                    .entry(cmd.to_lowercase())
                    .or_default()
                    .merge(stat);
            }
        }
        local_map.clear();
    });
}

pub fn reset_local_cmd_stats() {
    LOCAL_CMD_STATS.with(|stats| stats.borrow_mut().clear());
    LOCAL_CMD_COUNT.with(|count| count.set(0));
}

pub static LATENCY_MONITOR_THRESHOLD: std::sync::atomic::AtomicI64 =
    std::sync::atomic::AtomicI64::new(0);
pub static LATENCY_EVENTS: std::sync::LazyLock<
    std::sync::RwLock<std::collections::BTreeMap<String, Vec<(u64, u64)>>>,
> = std::sync::LazyLock::new(|| std::sync::RwLock::new(std::collections::BTreeMap::new()));

/// Name a command is counted under in INFO commandstats and LATENCY
/// HISTOGRAM: [`get_cmd_name`], with CONFIG split into its subcommands
/// like Redis does.
fn stat_cmd_name(cmd: &Command) -> &'static str {
    match cmd {
        Command::ConfigGet(_) => "config|get",
        Command::ConfigSet(pairs) => match pairs.first() {
            Some((p, _)) if p.eq_ignore_ascii_case(b"resetstat") => "config|resetstat",
            Some((p, _)) if p.eq_ignore_ascii_case(b"rewrite") => "config|rewrite",
            _ => "config|set",
        },
        _ => get_cmd_name(cmd),
    }
}

pub fn record_latency_event(event: &str, latency_ms: u64) {
    let thresh = LATENCY_MONITOR_THRESHOLD.load(std::sync::atomic::Ordering::Relaxed);
    if thresh <= 0 || latency_ms < thresh as u64 {
        return;
    }
    let now_sec = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    if let Ok(mut map) = LATENCY_EVENTS.write() {
        let samples = map.entry(event.to_string()).or_default();
        if let Some(last) = samples.last_mut()
            && last.0 == now_sec
        {
            if latency_ms > last.1 {
                last.1 = latency_ms;
            }
            return;
        }
        samples.push((now_sec, latency_ms));
    }
}

pub fn write_latency_response(sub: &LatencySubcommand, out: &mut Vec<u8>) {
    match sub {
        LatencySubcommand::Latest => {
            let map = LATENCY_EVENTS.read().unwrap();
            let active: Vec<_> = map.iter().filter(|(_, s)| !s.is_empty()).collect();
            write_resp_array_header(out, active.len());
            for (ev, samples) in active {
                let &(last_ts, last_lat) = samples.last().unwrap();
                let max_lat = samples.iter().map(|&(_, l)| l).max().unwrap_or(last_lat);
                write_resp_array_header(out, 4);
                write_resp_bulk(out, ev.as_bytes());
                write_resp_integer(out, last_ts as i64);
                write_resp_integer(out, last_lat as i64);
                write_resp_integer(out, max_lat as i64);
            }
        }
        LatencySubcommand::History(ev) => {
            if ev.is_empty() {
                out.extend_from_slice(
                    b"-ERR wrong number of arguments for 'latency history' command\r\n",
                );
            } else {
                let map = LATENCY_EVENTS.read().unwrap();
                if let Some(samples) = map.get(ev) {
                    write_resp_array_header(out, samples.len());
                    for &(ts, lat) in samples {
                        write_resp_array_header(out, 2);
                        write_resp_integer(out, ts as i64);
                        write_resp_integer(out, lat as i64);
                    }
                } else {
                    out.extend_from_slice(b"*0\r\n");
                }
            }
        }
        LatencySubcommand::Doctor => {
            out.extend_from_slice(b"+Dave, no latency spikes observed in your instance.\r\n");
        }
        LatencySubcommand::Reset(events) => {
            let mut map = LATENCY_EVENTS.write().unwrap();
            let count = if events.is_empty() {
                let n = map.len() as i64;
                map.clear();
                n
            } else {
                let mut n = 0;
                for ev in events {
                    if map.remove(ev).is_some() {
                        n += 1;
                    }
                }
                n
            };
            write_resp_integer(out, count);
        }
        LatencySubcommand::Graph(ev) => {
            if ev.is_empty() {
                out.extend_from_slice(
                    b"-ERR wrong number of arguments for 'latency graph' command\r\n",
                );
            } else {
                let map = LATENCY_EVENTS.read().unwrap();
                if let Some(samples) = map.get(ev)
                    && !samples.is_empty()
                {
                    let high = samples.iter().map(|&(_, l)| l).max().unwrap_or(0);
                    let low = samples.iter().map(|&(_, l)| l).min().unwrap_or(0);
                    let graph = format!(
                        "{} - high {} ms, low {} ms (all time high {} ms)\n--------------------------------------------------------------------------------\n",
                        ev, high, low, high
                    );
                    write_resp_bulk(out, graph.as_bytes());
                } else {
                    let err = format!("-ERR No samples available for event '{}'\r\n", ev);
                    out.extend_from_slice(err.as_bytes());
                }
            }
        }
        LatencySubcommand::Histogram(cmds) => {
            // Callers flush every shard's pending stats first.
            let map = CMD_STATS.read().unwrap();
            let wanted: Vec<String> = cmds.iter().map(|c| c.to_lowercase()).collect();
            let mut matched: Vec<(&String, &CmdStat)> = map
                .iter()
                .filter(|&(k, stat)| {
                    stat.calls > 0
                        && (wanted.is_empty()
                            || wanted.iter().any(|c| {
                                k == c
                                    || (k.starts_with(c.as_str()) && k[c.len()..].starts_with('|'))
                            }))
                })
                .collect();
            matched.sort_by(|a, b| a.0.cmp(b.0));
            write_resp_array_header(out, matched.len() * 2);
            for (k, stat) in matched {
                write_resp_bulk(out, k.as_bytes());
                write_resp_array_header(out, 4);
                write_resp_bulk(out, b"calls");
                write_resp_integer(out, stat.calls as i64);
                write_resp_bulk(out, b"histogram_usec");
                // Like Redis: (bucket upper bound in usec, cumulative calls)
                // for every non-empty power-of-two bucket.
                let buckets = stat.hist.iter().filter(|&&n| n > 0).count();
                write_resp_array_header(out, buckets * 2);
                let mut cumulative = 0u64;
                for (i, &n) in stat.hist.iter().enumerate() {
                    if n > 0 {
                        cumulative += n;
                        write_resp_integer(out, 1i64 << i);
                        write_resp_integer(out, cumulative as i64);
                    }
                }
            }
        }
        LatencySubcommand::Help => {
            let help_lines = [
                "LATENCY <subcommand> [<arg> [value] [opt] ...]. Subcommands are:",
                "DOCTOR",
                "    Return a human readable latency analysis report.",
                "GRAPH <event>",
                "    Return an ASCII latency graph for the <event> class.",
                "HISTORY <event>",
                "    Return time-latency samples for the <event> class.",
                "LATEST",
                "    Return the latest latency samples for all events.",
                "RESET [<event> ...]",
                "    Reset latency data of one or more <event> classes.",
                "    (default: reset all data for all event classes)",
                "HISTOGRAM [<command> ...]",
                "    Return a cumulative distribution of latencies in the format of a histogram for the specified command names, or all commands if no command name is specified.",
                "HELP",
                "    Print this help.",
            ];
            out.extend_from_slice(format!("*{}\r\n", help_lines.len()).as_bytes());
            for line in help_lines {
                out.extend_from_slice(format!("${}\r\n{}\r\n", line.len(), line).as_bytes());
            }
        }
    }
}

pub static PAUSE_DEADLINE_MS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
pub static PAUSE_WRITE_ONLY: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);
pub static PAUSED_CLIENTS: std::sync::LazyLock<
    std::sync::Mutex<Vec<(u16, u64, flume::Sender<()>)>>,
> = std::sync::LazyLock::new(|| std::sync::Mutex::new(Vec::new()));

#[inline]
pub fn now_epoch_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64
}

pub fn set_client_pause(timeout_ms: u64, write_only: bool) {
    if timeout_ms == 0 {
        let _ = unpause_clients();
        return;
    }
    let now = now_epoch_ms();
    let new_deadline = now.saturating_add(timeout_ms);
    let old_deadline = PAUSE_DEADLINE_MS.load(std::sync::atomic::Ordering::SeqCst);
    if old_deadline > now {
        let old_write_only = PAUSE_WRITE_ONLY.load(std::sync::atomic::Ordering::SeqCst);
        let merged_write_only = old_write_only && write_only;
        let merged_deadline = old_deadline.max(new_deadline);
        PAUSE_WRITE_ONLY.store(merged_write_only, std::sync::atomic::Ordering::SeqCst);
        PAUSE_DEADLINE_MS.store(merged_deadline, std::sync::atomic::Ordering::SeqCst);
    } else {
        PAUSE_WRITE_ONLY.store(write_only, std::sync::atomic::Ordering::SeqCst);
        PAUSE_DEADLINE_MS.store(new_deadline, std::sync::atomic::Ordering::SeqCst);
    }
}

pub fn unpause_clients() -> usize {
    PAUSE_DEADLINE_MS.store(0, std::sync::atomic::Ordering::SeqCst);
    let mut list = PAUSED_CLIENTS.lock().unwrap();
    let woken = list.len();
    for (_, _, tx) in list.drain(..) {
        let _ = tx.send(());
    }
    woken
}

#[inline]
pub fn is_client_paused() -> Option<(u64, bool)> {
    let dl = PAUSE_DEADLINE_MS.load(std::sync::atomic::Ordering::Relaxed);
    if dl == 0 {
        return None;
    }
    let now = now_epoch_ms();
    if now >= dl {
        let _ = unpause_clients();
        return None;
    }
    let write_only = PAUSE_WRITE_ONLY.load(std::sync::atomic::Ordering::Relaxed);
    Some((dl - now, write_only))
}

#[inline]
pub fn paused_clients_count() -> usize {
    if is_client_paused().is_none() {
        return 0;
    }
    PAUSED_CLIENTS.lock().unwrap().len()
}

pub fn should_pause_command(cmd: &Command, write_only: bool) -> bool {
    if matches!(
        cmd,
        Command::Client(ClientSubcommand::Unpause | ClientSubcommand::Pause(..)) | Command::Quit
    ) {
        return false;
    }
    if !write_only {
        return true;
    }
    match cmd {
        Command::Eval {
            script, read_only, ..
        } => !*read_only && !crate::scripting::is_script_read_only(script),
        Command::Evalsha { sha, read_only, .. } => {
            !*read_only && !crate::scripting::is_sha_read_only(sha)
        }
        Command::Fcall {
            function,
            read_only,
            ..
        } => !*read_only && !crate::scripting::is_function_read_only(function),
        Command::Publish { .. }
        | Command::Spublish { .. }
        | Command::Pfcount { .. }
        | Command::Blpop { .. }
        | Command::Brpop { .. }
        | Command::Blmove { .. }
        | Command::Blmovem { .. }
        | Command::Blmpop { .. }
        | Command::Bzpopmin { .. }
        | Command::Bzpopmax { .. }
        | Command::Bzmpop { .. }
        | Command::Xreadgroup { .. } => true,
        _ => cmd.is_write_command(),
    }
}

struct PausedClientGuard {
    client_id: u64,
}

impl Drop for PausedClientGuard {
    fn drop(&mut self) {
        let mut list = PAUSED_CLIENTS.lock().unwrap();
        list.retain(|&(_, cid, _)| cid != self.client_id);
    }
}

pub async fn wait_if_client_paused(port: u16, client_id: u64, cmd: &Command) {
    if IN_TX.get() {
        return;
    }
    while let Some((rem_ms, write_only)) = is_client_paused() {
        if !should_pause_command(cmd, write_only) {
            return;
        }
        let (tx, rx) = flume::bounded(1);
        {
            let mut list = PAUSED_CLIENTS.lock().unwrap();
            if !list.iter().any(|&(_, cid, _)| cid == client_id) {
                list.push((port, client_id, tx));
            }
        }
        let _guard = PausedClientGuard { client_id };
        let _ = monoio::time::timeout(
            std::time::Duration::from_millis(rem_ms.max(1)),
            rx.recv_async(),
        )
        .await;
        drop(_guard);
        if now_epoch_ms() >= PAUSE_DEADLINE_MS.load(std::sync::atomic::Ordering::Relaxed) {
            let _ = unpause_clients();
            return;
        }
    }
}

pub async fn wait_if_tx_paused(port: u16, client_id: u64, tx_queue: &[Command]) {
    while let Some((rem_ms, write_only)) = is_client_paused() {
        let should_pause =
            !write_only || tx_queue.iter().any(|c| should_pause_command(c, write_only));
        if !should_pause {
            return;
        }
        let (tx, rx) = flume::bounded(1);
        {
            let mut list = PAUSED_CLIENTS.lock().unwrap();
            if !list.iter().any(|&(_, cid, _)| cid == client_id) {
                list.push((port, client_id, tx));
            }
        }
        let _guard = PausedClientGuard { client_id };
        let _ = monoio::time::timeout(
            std::time::Duration::from_millis(rem_ms.max(1)),
            rx.recv_async(),
        )
        .await;
        drop(_guard);
        if now_epoch_ms() >= PAUSE_DEADLINE_MS.load(std::sync::atomic::Ordering::Relaxed) {
            let _ = unpause_clients();
            return;
        }
    }
}

pub static TOTAL_ERROR_REPLIES: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
pub static ERROR_STATS: std::sync::LazyLock<std::sync::RwLock<hashbrown::HashMap<String, u64>>> =
    std::sync::LazyLock::new(|| std::sync::RwLock::new(hashbrown::HashMap::new()));
pub static FAILED_CMD_STATS: std::sync::LazyLock<
    std::sync::RwLock<hashbrown::HashMap<String, u64>>,
> = std::sync::LazyLock::new(|| std::sync::RwLock::new(hashbrown::HashMap::new()));
pub static REJECTED_CMD_STATS: std::sync::LazyLock<
    std::sync::RwLock<hashbrown::HashMap<String, u64>>,
> = std::sync::LazyLock::new(|| std::sync::RwLock::new(hashbrown::HashMap::new()));

pub fn record_rejected_stat(cmd_name: &str) {
    if let Ok(mut map) = REJECTED_CMD_STATS.write() {
        *map.entry(cmd_name.to_lowercase()).or_insert(0) += 1;
    }
}

pub fn record_failed_stat(cmd_name: &str) {
    if let Ok(mut map) = FAILED_CMD_STATS.write() {
        *map.entry(cmd_name.to_lowercase()).or_insert(0) += 1;
    }
}

pub fn record_error_stat(prefix: &str, cmd_name: Option<&str>) {
    TOTAL_ERROR_REPLIES.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if let Ok(mut map) = ERROR_STATS.write() {
        *map.entry(prefix.to_string()).or_insert(0) += 1;
    }
    if let Some(cmd) = cmd_name
        && let Ok(mut map) = FAILED_CMD_STATS.write()
    {
        *map.entry(cmd.to_lowercase()).or_insert(0) += 1;
    }
}

pub fn reset_error_stats() {
    TOTAL_ERROR_REPLIES.store(0, std::sync::atomic::Ordering::Relaxed);
    if let Ok(mut map) = ERROR_STATS.write() {
        map.clear();
    }
    if let Ok(mut map) = FAILED_CMD_STATS.write() {
        map.clear();
    }
    if let Ok(mut map) = REJECTED_CMD_STATS.write() {
        map.clear();
    }
}

pub static HAS_WATCHED_KEYS: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn watch_keys(port: u16, client_id: u64, keys: &[Bytes]) {
    if keys.is_empty() {
        return;
    }
    HAS_WATCHED_KEYS.store(true, std::sync::atomic::Ordering::Relaxed);
    let mut map = WATCHED_KEYS.write().unwrap();
    let port_map = map.entry(port).or_default();
    for k in keys {
        port_map.entry(k.clone()).or_default().insert(client_id);
    }
    CLIENT_WATCH_TAINTED
        .write()
        .unwrap()
        .entry((port, client_id))
        .or_insert(false);
}

pub fn unwatch_keys(port: u16, client_id: u64) {
    if !HAS_WATCHED_KEYS.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let mut map = WATCHED_KEYS.write().unwrap();
    if let Some(port_map) = map.get_mut(&port) {
        for set in port_map.values_mut() {
            set.remove(&client_id);
        }
    }
    CLIENT_WATCH_TAINTED
        .write()
        .unwrap()
        .remove(&(port, client_id));
    if map.values().all(|pm| pm.values().all(|s| s.is_empty())) {
        HAS_WATCHED_KEYS.store(false, std::sync::atomic::Ordering::Relaxed);
    }
}

pub fn is_watch_tainted(port: u16, client_id: u64) -> bool {
    if !HAS_WATCHED_KEYS.load(std::sync::atomic::Ordering::Relaxed) {
        return false;
    }
    CLIENT_WATCH_TAINTED
        .read()
        .unwrap()
        .get(&(port, client_id))
        .copied()
        .unwrap_or(false)
}

#[inline(always)]
pub fn touch_watched_key(port: u16, key: &[u8]) {
    if !HAS_WATCHED_KEYS.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let map = WATCHED_KEYS.read().unwrap();
    if let Some(port_map) = map.get(&port)
        && let Some(clients) = port_map.get(key)
    {
        let mut tainted = CLIENT_WATCH_TAINTED.write().unwrap();
        for &cid in clients {
            tainted.insert((port, cid), true);
        }
    }
}

#[inline(always)]
pub fn touch_watched_key_any_port(key: &[u8]) {
    if !HAS_WATCHED_KEYS.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let map = WATCHED_KEYS.read().unwrap();
    let mut tainted = CLIENT_WATCH_TAINTED.write().unwrap();
    for (&port, port_map) in map.iter() {
        if let Some(clients) = port_map.get(key) {
            for &cid in clients {
                tainted.insert((port, cid), true);
            }
        }
    }
}

static GLOBAL_CLIENTS: std::sync::LazyLock<
    std::sync::RwLock<hashbrown::HashMap<(u16, u64), GlobalClientEntry>>,
> = std::sync::LazyLock::new(|| std::sync::RwLock::new(hashbrown::HashMap::new()));

pub static ACTIVE_COMMAND_PORT: std::sync::atomic::AtomicU16 = std::sync::atomic::AtomicU16::new(0);

pub fn inc_active_client_tot_cmds() {
    let port = ACTIVE_COMMAND_PORT.load(std::sync::atomic::Ordering::Relaxed);
    let cid = ACTIVE_COMMAND_CLIENT_ID.load(std::sync::atomic::Ordering::Relaxed);
    if cid > 0
        && let Some(entry) = GLOBAL_CLIENTS.read().unwrap().get(&(port, cid))
    {
        entry
            .stats
            .tot_cmds
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }
}

pub static HAS_MONITOR_CLIENTS: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

static MONITOR_CLIENTS: std::sync::LazyLock<
    std::sync::RwLock<Vec<(u16, u64, std::os::unix::io::RawFd)>>,
> = std::sync::LazyLock::new(|| std::sync::RwLock::new(Vec::new()));

#[inline(always)]
pub fn has_monitor_clients() -> bool {
    HAS_MONITOR_CLIENTS.load(std::sync::atomic::Ordering::Relaxed)
}

pub fn register_monitor_client(port: u16, client_id: u64, raw_fd: std::os::unix::io::RawFd) {
    let mut list = MONITOR_CLIENTS.write().unwrap();
    if !list.iter().any(|&(p, id, _)| p == port && id == client_id) {
        list.push((port, client_id, raw_fd));
    }
    HAS_MONITOR_CLIENTS.store(!list.is_empty(), std::sync::atomic::Ordering::Release);
}

pub fn unregister_monitor_client(port: u16, client_id: u64) {
    if !has_monitor_clients() {
        return;
    }
    let mut list = MONITOR_CLIENTS.write().unwrap();
    let prev_len = list.len();
    list.retain(|&(p, id, _)| !(p == port && id == client_id));
    if list.len() != prev_len {
        HAS_MONITOR_CLIENTS.store(!list.is_empty(), std::sync::atomic::Ordering::Release);
    }
}

pub fn broadcast_monitor(port: u16, source_addr: &str, argv: &[Bytes]) {
    if !has_monitor_clients() || argv.is_empty() {
        return;
    }
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default();
    let mut line = format!(
        "+{}.{:06} [0 {}]",
        now.as_secs(),
        now.subsec_micros(),
        source_addr
    );
    for arg in argv {
        line.push_str(" \"");
        for &b in arg.iter() {
            match b {
                b'\\' => line.push_str("\\\\"),
                b'"' => line.push_str("\\\""),
                b'\n' => line.push_str("\\n"),
                b'\r' => line.push_str("\\r"),
                b'\t' => line.push_str("\\t"),
                0x20..=0x7e => line.push(b as char),
                _ => line.push_str(&format!("\\x{:02x}", b)),
            }
        }
        line.push('"');
    }
    line.push_str("\r\n");
    let bytes = line.as_bytes();
    let list = MONITOR_CLIENTS.read().unwrap();
    for &(p, _, fd) in list.iter() {
        if p == port {
            unsafe {
                libc::send(
                    fd,
                    bytes.as_ptr() as *const libc::c_void,
                    bytes.len(),
                    libc::MSG_DONTWAIT | libc::MSG_NOSIGNAL,
                );
            }
        }
    }
}

pub static RDB_KEY_SAVE_DELAY: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
pub static RDB_BGSAVE_IN_PROGRESS: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn register_global_client(
    port: u16,
    client_id: u64,
    raw_fd: std::os::unix::io::RawFd,
    track_tx: flume::Sender<Vec<u8>>,
    is_resp3: bool,
    auth_user: String,
    is_pubsub: bool,
    stats: std::sync::Arc<ClientStats>,
) {
    GLOBAL_CLIENTS.write().unwrap().insert(
        (port, client_id),
        GlobalClientEntry {
            raw_fd,
            track_tx,
            is_resp3,
            auth_user,
            is_pubsub,
            stats,
        },
    );
}

pub fn unregister_global_client(port: u16, client_id: u64) {
    GLOBAL_CLIENTS.write().unwrap().remove(&(port, client_id));
}

pub fn update_global_client_resp3(port: u16, client_id: u64, is_resp3: bool) {
    if let Some(entry) = GLOBAL_CLIENTS.write().unwrap().get_mut(&(port, client_id)) {
        entry.is_resp3 = is_resp3;
    }
}

pub fn update_global_client_auth(port: u16, client_id: u64, auth_user: &str) {
    if let Some(entry) = GLOBAL_CLIENTS.write().unwrap().get_mut(&(port, client_id)) {
        entry.auth_user = auth_user.to_string();
    }
}

pub fn update_global_client_pubsub(port: u16, client_id: u64, is_pubsub: bool) {
    if let Some(entry) = GLOBAL_CLIENTS.write().unwrap().get_mut(&(port, client_id)) {
        entry.is_pubsub = is_pubsub;
    }
}

static TRACKING_CLIENTS: std::sync::LazyLock<
    std::sync::RwLock<hashbrown::HashMap<(u16, u64), ClientTracker>>,
> = std::sync::LazyLock::new(|| std::sync::RwLock::new(hashbrown::HashMap::new()));

pub static HAS_TRACKING_CLIENTS: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub static TRACKING_TABLE_MAX_KEYS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(1_000_000);

#[allow(clippy::too_many_arguments)]
pub fn register_client_tracking(
    port: u16,
    client_id: u64,
    redirect: Option<i64>,
    bcast: bool,
    mut prefixes: Vec<Bytes>,
    optin: bool,
    optout: bool,
    noloop: bool,
) -> Result<(), String> {
    let redirect_id = match redirect {
        Some(id) if id < 0 => {
            return Err("REDIRECT client ID must be a positive integer".to_string());
        }
        Some(id) => id as u64,
        None => 0,
    };
    if redirect_id > 0 {
        let clients = GLOBAL_CLIENTS.read().unwrap();
        if !clients.contains_key(&(port, redirect_id)) {
            return Err("The client ID you want to redirect to does not exist".to_string());
        }
    }

    if bcast && prefixes.is_empty() {
        prefixes.push(Bytes::new());
    }

    // Check overlap among provided prefixes
    if bcast {
        for i in 0..prefixes.len() {
            for j in (i + 1)..prefixes.len() {
                if prefixes[i].starts_with(&prefixes[j]) || prefixes[j].starts_with(&prefixes[i]) {
                    return Err(format!(
                        "Prefix '{}' overlaps with another provided prefix '{}'",
                        String::from_utf8_lossy(&prefixes[i]),
                        String::from_utf8_lossy(&prefixes[j])
                    ));
                }
            }
        }
    }

    let mut map = TRACKING_CLIENTS.write().unwrap();
    if let Some(existing) = map.get_mut(&(port, client_id))
        && existing.bcast
        && bcast
    {
        for new_p in &prefixes {
            for old_p in &existing.prefixes {
                if new_p != old_p
                    && (new_p.starts_with(old_p.as_ref()) || old_p.starts_with(new_p.as_ref()))
                {
                    return Err(format!(
                        "Prefix '{}' overlaps with an existing prefix '{}'",
                        String::from_utf8_lossy(new_p),
                        String::from_utf8_lossy(old_p)
                    ));
                }
            }
        }
        for new_p in prefixes {
            if !existing.prefixes.contains(&new_p) {
                existing.prefixes.push(new_p);
            }
        }
        existing.redirect_id = redirect_id;
        existing.broken_redirect = false;
        existing.noloop = noloop;
        HAS_TRACKING_CLIENTS.store(true, std::sync::atomic::Ordering::Release);
        return Ok(());
    }

    map.insert(
        (port, client_id),
        ClientTracker {
            port,
            client_id,
            redirect_id,
            broken_redirect: false,
            bcast,
            prefixes,
            optin,
            optout,
            noloop,
            caching: None,
            tracked_keys: hashbrown::HashSet::new(),
            pending_bcast: Vec::new(),
        },
    );
    HAS_TRACKING_CLIENTS.store(!map.is_empty(), std::sync::atomic::Ordering::Release);
    Ok(())
}

pub fn unregister_client_tracking(port: u16, client_id: u64) {
    if !HAS_TRACKING_CLIENTS.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let mut map = TRACKING_CLIENTS.write().unwrap();
    if map.remove(&(port, client_id)).is_some() {
        HAS_TRACKING_CLIENTS.store(!map.is_empty(), std::sync::atomic::Ordering::Release);
    }
}

pub fn set_client_caching(
    port: u16,
    client_id: u64,
    yes_opt: Option<bool>,
) -> Result<(), &'static str> {
    if !HAS_TRACKING_CLIENTS.load(std::sync::atomic::Ordering::Relaxed) {
        return Err(
            "CLIENT CACHING can be called only when the client is in tracking mode with OPTIN or OPTOUT mode enabled",
        );
    }
    let mut map = TRACKING_CLIENTS.write().unwrap();
    let Some(tracker) = map.get_mut(&(port, client_id)) else {
        return Err(
            "CLIENT CACHING can be called only when the client is in tracking mode with OPTIN or OPTOUT mode enabled",
        );
    };
    if (!tracker.optin && !tracker.optout) || tracker.bcast {
        return Err(
            "CLIENT CACHING can be called only when the client is in tracking mode with OPTIN or OPTOUT mode enabled",
        );
    }
    let Some(yes) = yes_opt else {
        return Err("syntax error");
    };
    if yes && !tracker.optin {
        return Err("CLIENT CACHING YES is only valid when OPTIN is enabled");
    }
    if !yes && !tracker.optout {
        return Err("CLIENT CACHING NO is only valid when OPTOUT is enabled");
    }
    tracker.caching = Some(yes);
    Ok(())
}

#[inline(always)]
pub fn reset_client_caching(port: u16, client_id: u64) {
    if !HAS_TRACKING_CLIENTS.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let mut map = TRACKING_CLIENTS.write().unwrap();
    if let Some(tracker) = map.get_mut(&(port, client_id)) {
        tracker.caching = None;
    }
}

pub fn get_client_redir(port: u16, client_id: u64) -> i64 {
    if !HAS_TRACKING_CLIENTS.load(std::sync::atomic::Ordering::Relaxed) {
        return -1;
    }
    let map = TRACKING_CLIENTS.read().unwrap();
    if let Some(tracker) = map.get(&(port, client_id)) {
        tracker.redirect_id as i64
    } else {
        -1
    }
}

pub fn write_client_tracking_info(port: u16, client_id: u64, is_resp3: bool, out: &mut Vec<u8>) {
    let map = TRACKING_CLIENTS.read().unwrap();
    let tracker_opt = map.get(&(port, client_id));

    let mut flags: Vec<&'static str> = Vec::new();
    let redirect: i64;
    let mut prefixes: Vec<Bytes> = Vec::new();

    if let Some(t) = tracker_opt {
        flags.push("on");
        if t.bcast {
            flags.push("bcast");
        }
        if t.optin {
            flags.push("optin");
        }
        if t.optout {
            flags.push("optout");
        }
        if t.caching == Some(true) {
            flags.push("caching-yes");
        } else if t.caching == Some(false) {
            flags.push("caching-no");
        }
        if t.noloop {
            flags.push("noloop");
        }
        if t.broken_redirect {
            flags.push("broken_redirect");
        }
        redirect = t.redirect_id as i64;
        if t.bcast {
            prefixes = t.prefixes.clone();
        }
    } else {
        flags.push("off");
        redirect = -1;
    }

    if is_resp3 {
        out.extend_from_slice(b"%3\r\n");
    } else {
        out.extend_from_slice(b"*6\r\n");
    }
    write_resp_bulk(out, b"flags");
    if is_resp3 {
        out.extend_from_slice(format!("~{}\r\n", flags.len()).as_bytes());
    } else {
        out.extend_from_slice(format!("*{}\r\n", flags.len()).as_bytes());
    }
    for f in flags {
        write_resp_bulk(out, f.as_bytes());
    }
    write_resp_bulk(out, b"redirect");
    write_resp_integer(out, redirect);
    write_resp_bulk(out, b"prefixes");
    out.extend_from_slice(format!("*{}\r\n", prefixes.len()).as_bytes());
    for p in prefixes {
        write_resp_bulk(out, &p);
    }
}

pub fn get_tracking_info_stats(port: u16) -> (usize, usize, usize, usize) {
    if !HAS_TRACKING_CLIENTS.load(std::sync::atomic::Ordering::Relaxed) {
        return (0, 0, 0, 0);
    }
    let map = TRACKING_CLIENTS.read().unwrap();
    let mut tracking_clients = 0usize;
    let mut tracking_total_items = 0usize;
    let mut unique_keys: hashbrown::HashSet<&[u8]> = hashbrown::HashSet::new();
    let mut tracking_total_prefixes = 0usize;

    for tracker in map.values() {
        if tracker.port != port {
            continue;
        }
        tracking_clients += 1;
        if tracker.bcast {
            tracking_total_prefixes += tracker.prefixes.len();
        } else {
            tracking_total_items += tracker.tracked_keys.len();
            for k in &tracker.tracked_keys {
                unique_keys.insert(k.as_slice());
            }
        }
    }
    (
        tracking_clients,
        tracking_total_items,
        unique_keys.len(),
        tracking_total_prefixes,
    )
}

fn send_raw_to_client_entry(target_id: u64, entry: &GlobalClientEntry, msg: Vec<u8>) {
    let exec_cid = {
        let local = EXECUTING_CLIENT_ID.get();
        if local != 0 {
            local
        } else {
            ACTIVE_COMMAND_CLIENT_ID.load(std::sync::atomic::Ordering::Relaxed)
        }
    };
    if target_id == exec_cid {
        if IN_MAXMEMORY_EVICT.get()
            || IN_MAXMEMORY_EVICT_GLOBAL.load(std::sync::atomic::Ordering::Relaxed)
        {
            PRE_CMD_TRACK_BUF_GLOBAL
                .lock()
                .unwrap()
                .extend_from_slice(&msg);
        } else {
            let _ = entry.track_tx.send(msg);
        }
    } else {
        unsafe {
            libc::send(
                entry.raw_fd,
                msg.as_ptr() as *const libc::c_void,
                msg.len(),
                libc::MSG_DONTWAIT | libc::MSG_NOSIGNAL,
            );
        }
    }
}

fn format_invalidation_msg(
    is_resp3: bool,
    is_redir_or_pubsub: bool,
    keys: Option<&[&[u8]]>,
) -> Option<Vec<u8>> {
    if is_resp3 {
        let mut msg = Vec::new();
        match keys {
            Some(ks) => {
                msg.extend_from_slice(
                    format!(">2\r\n$10\r\ninvalidate\r\n*{}\r\n", ks.len()).as_bytes(),
                );
                for k in ks {
                    write_resp_bulk(&mut msg, k);
                }
            }
            None => {
                msg.extend_from_slice(b">2\r\n$10\r\ninvalidate\r\n_\r\n");
            }
        }
        Some(msg)
    } else if is_redir_or_pubsub {
        let mut msg = Vec::new();
        match keys {
            Some(ks) => {
                msg.extend_from_slice(
                    format!(
                        "*3\r\n$7\r\nmessage\r\n$20\r\n__redis__:invalidate\r\n*{}\r\n",
                        ks.len()
                    )
                    .as_bytes(),
                );
                for k in ks {
                    write_resp_bulk(&mut msg, k);
                }
            }
            None => {
                msg.extend_from_slice(
                    b"*3\r\n$7\r\nmessage\r\n$20\r\n__redis__:invalidate\r\n$-1\r\n",
                );
            }
        }
        Some(msg)
    } else {
        None
    }
}

fn deliver_invalidation_to_tracker(
    tracker: &mut ClientTracker,
    clients: &hashbrown::HashMap<(u16, u64), GlobalClientEntry>,
    keys: Option<&[&[u8]]>,
) {
    let target_id = if tracker.redirect_id > 0 {
        tracker.redirect_id
    } else {
        tracker.client_id
    };
    if let Some(target_entry) = clients.get(&(tracker.port, target_id)) {
        let is_redir_or_pubsub = tracker.redirect_id > 0 || target_entry.is_pubsub;
        if let Some(msg) = format_invalidation_msg(target_entry.is_resp3, is_redir_or_pubsub, keys)
        {
            send_raw_to_client_entry(target_id, target_entry, msg);
        }
    } else if tracker.redirect_id > 0 {
        tracker.broken_redirect = true;
        if let Some(owner_entry) = clients.get(&(tracker.port, tracker.client_id))
            && owner_entry.is_resp3
        {
            let msg = format!(
                ">2\r\n$21\r\ntracking-redir-broken\r\n:{}\r\n",
                tracker.redirect_id
            )
            .into_bytes();
            send_raw_to_client_entry(tracker.client_id, owner_entry, msg);
        }
    }
}

fn can_tracker_read_key(
    port: u16,
    client_id: u64,
    clients: &hashbrown::HashMap<(u16, u64), GlobalClientEntry>,
    key: &[u8],
) -> bool {
    let user_name = clients
        .get(&(port, client_id))
        .map(|c| c.auth_user.as_str())
        .unwrap_or("default");
    if !crate::acl::HAS_CUSTOM_ACL.load(std::sync::atomic::Ordering::Relaxed)
        && user_name == "default"
    {
        return true;
    }
    let acl = crate::acl::get_acl_for_port(port);
    let guard = acl.read().unwrap();
    guard
        .users
        .get(user_name)
        .map(|u| u.can_access_key(key, crate::acl::KEY_READ))
        .unwrap_or(true)
}

pub fn enforce_tracking_max_keys(port: u16) {
    if !HAS_TRACKING_CLIENTS.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let max_keys = TRACKING_TABLE_MAX_KEYS.load(std::sync::atomic::Ordering::Relaxed);
    let mut map = TRACKING_CLIENTS.write().unwrap();
    let clients = GLOBAL_CLIENTS.read().unwrap();

    loop {
        let total_keys: usize = map
            .values()
            .filter(|t| t.port == port && !t.bcast)
            .map(|t| t.tracked_keys.len())
            .sum();
        if total_keys <= max_keys {
            break;
        }
        let mut evicted_any = false;
        for tracker in map.values_mut() {
            if tracker.port != port || tracker.bcast || tracker.tracked_keys.is_empty() {
                continue;
            }
            if let Some(k) = tracker.tracked_keys.iter().next().cloned() {
                tracker.tracked_keys.remove(&k);
                deliver_invalidation_to_tracker(tracker, &clients, Some(&[k.as_slice()]));
                evicted_any = true;
                break;
            }
        }
        if !evicted_any {
            break;
        }
    }
}

#[inline(always)]
pub fn record_client_read(port: u16, client_id: u64, key: &[u8]) {
    if !HAS_TRACKING_CLIENTS.load(std::sync::atomic::Ordering::Relaxed) || client_id == 0 {
        return;
    }
    let needs_evict = {
        let mut map = TRACKING_CLIENTS.write().unwrap();
        if let Some(tracker) = map.get_mut(&(port, client_id))
            && !tracker.bcast
        {
            if tracker.optin && tracker.caching != Some(true) {
                return;
            }
            if tracker.optout && tracker.caching == Some(false) {
                return;
            }
            tracker.tracked_keys.insert(key.to_vec());
            let max_keys = TRACKING_TABLE_MAX_KEYS.load(std::sync::atomic::Ordering::Relaxed);
            tracker.tracked_keys.len() > max_keys
        } else {
            false
        }
    };
    if needs_evict {
        enforce_tracking_max_keys(port);
    }
}

pub fn notify_key_invalidation(port: u16, key: &[u8], sender_client_id: u64) {
    touch_watched_key(port, key);
    if !HAS_TRACKING_CLIENTS.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let defer_bcast = DEFER_BCAST_FLUSH.get()
        || DEFER_BCAST_FLUSH_GLOBAL.load(std::sync::atomic::Ordering::Relaxed);
    let mut map = TRACKING_CLIENTS.write().unwrap();
    let clients = GLOBAL_CLIENTS.read().unwrap();
    for tracker in map.values_mut() {
        if tracker.port != port {
            continue;
        }
        if tracker.noloop && sender_client_id != 0 && tracker.client_id == sender_client_id {
            if !tracker.bcast {
                tracker.tracked_keys.remove(key);
            }
            continue;
        }
        if tracker.bcast {
            if !can_tracker_read_key(port, tracker.client_id, &clients, key) {
                continue;
            }
            for pfx_idx in 0..tracker.prefixes.len() {
                if key.starts_with(&tracker.prefixes[pfx_idx]) {
                    if defer_bcast {
                        let pfx = tracker.prefixes[pfx_idx].clone();
                        if let Some((_, list)) =
                            tracker.pending_bcast.iter_mut().find(|(p, _)| *p == pfx)
                        {
                            if !list.iter().any(|k| k.as_slice() == key) {
                                list.push(key.to_vec());
                            }
                        } else {
                            tracker.pending_bcast.push((pfx, vec![key.to_vec()]));
                        }
                    } else {
                        deliver_invalidation_to_tracker(tracker, &clients, Some(&[key]));
                    }
                }
            }
        } else if tracker.tracked_keys.remove(key)
            && can_tracker_read_key(port, tracker.client_id, &clients, key)
        {
            deliver_invalidation_to_tracker(tracker, &clients, Some(&[key]));
        }
    }
}

pub fn flush_pending_bcast(port: u16) {
    if !HAS_TRACKING_CLIENTS.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let mut map = TRACKING_CLIENTS.write().unwrap();
    let clients = GLOBAL_CLIENTS.read().unwrap();
    for tracker in map.values_mut() {
        if tracker.port == port && !tracker.pending_bcast.is_empty() {
            let pending = std::mem::take(&mut tracker.pending_bcast);
            for (_pfx, keys) in pending {
                let refs: Vec<&[u8]> = keys.iter().map(|k| k.as_slice()).collect();
                deliver_invalidation_to_tracker(tracker, &clients, Some(&refs));
            }
        }
    }
}

pub fn notify_key_invalidation_any_port(key: &[u8], sender_client_id: u64) {
    if !HAS_TRACKING_CLIENTS.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let ports: smallvec::SmallVec<[u16; 4]> = {
        let map = TRACKING_CLIENTS.read().unwrap();
        let mut p = smallvec::SmallVec::new();
        for &(port, _) in map.keys() {
            if !p.contains(&port) {
                p.push(port);
            }
        }
        p
    };
    for port in ports {
        notify_key_invalidation(port, key, sender_client_id);
    }
}

pub fn notify_flush_invalidation(port: u16, sender_client_id: u64) {
    if !HAS_TRACKING_CLIENTS.load(std::sync::atomic::Ordering::Relaxed) {
        return;
    }
    let mut map = TRACKING_CLIENTS.write().unwrap();
    let clients = GLOBAL_CLIENTS.read().unwrap();
    for tracker in map.values_mut() {
        if tracker.port != port {
            continue;
        }
        let had_keys = !tracker.tracked_keys.is_empty();
        tracker.tracked_keys.clear();
        tracker.pending_bcast.clear();
        if !tracker.bcast && !had_keys {
            continue;
        }
        if tracker.noloop && sender_client_id != 0 && tracker.client_id == sender_client_id {
            continue;
        }
        deliver_invalidation_to_tracker(tracker, &clients, None);
    }
}

#[inline(always)]
pub fn write_resp_integer(out: &mut Vec<u8>, val: i64) {
    match val {
        0 => out.extend_from_slice(b":0\r\n"),
        1 => out.extend_from_slice(b":1\r\n"),
        2 => out.extend_from_slice(b":2\r\n"),
        3 => out.extend_from_slice(b":3\r\n"),
        4 => out.extend_from_slice(b":4\r\n"),
        5 => out.extend_from_slice(b":5\r\n"),
        -1 => out.extend_from_slice(b":-1\r\n"),
        _ => {
            let mut buf = [0u8; 24];
            let mut i = buf.len();
            let neg = val < 0;
            let mut uval = if neg {
                if val == i64::MIN {
                    out.extend_from_slice(b":-9223372036854775808\r\n");
                    return;
                }
                (-val) as u64
            } else {
                val as u64
            };
            while uval > 0 {
                i -= 1;
                buf[i] = b'0' + (uval % 10) as u8;
                uval /= 10;
            }
            if neg {
                i -= 1;
                buf[i] = b'-';
            }
            out.push(b':');
            out.extend_from_slice(&buf[i..]);
            out.extend_from_slice(b"\r\n");
        }
    }
}

#[inline(always)]
pub fn write_resp_bulk(out: &mut Vec<u8>, val: &[u8]) {
    let v_len = val.len();
    out.reserve(v_len + 16);
    out.push(b'$');
    match v_len {
        0 => out.extend_from_slice(b"0\r\n"),
        1..=9 => {
            out.push(b'0' + v_len as u8);
            out.extend_from_slice(b"\r\n");
        }
        10..=99 => {
            let p = v_len * 2;
            out.push(crate::shard::DIGIT_PAIRS[p]);
            out.push(crate::shard::DIGIT_PAIRS[p + 1]);
            out.extend_from_slice(b"\r\n");
        }
        100..=999 => {
            let h = (v_len / 100) as u8;
            let p = (v_len % 100) * 2;
            out.push(b'0' + h);
            out.push(crate::shard::DIGIT_PAIRS[p]);
            out.push(crate::shard::DIGIT_PAIRS[p + 1]);
            out.extend_from_slice(b"\r\n");
        }
        1000..=9999 => {
            let p1 = (v_len / 100) * 2;
            let p2 = (v_len % 100) * 2;
            out.push(crate::shard::DIGIT_PAIRS[p1]);
            out.push(crate::shard::DIGIT_PAIRS[p1 + 1]);
            out.push(crate::shard::DIGIT_PAIRS[p2]);
            out.push(crate::shard::DIGIT_PAIRS[p2 + 1]);
            out.extend_from_slice(b"\r\n");
        }
        _ => {
            let mut buf = [0u8; 20];
            let mut i = buf.len();
            let mut uval = v_len;
            while uval > 0 {
                i -= 1;
                buf[i] = b'0' + (uval % 10) as u8;
                uval /= 10;
            }
            out.extend_from_slice(&buf[i..]);
            out.extend_from_slice(b"\r\n");
        }
    }
    out.extend_from_slice(val);
    out.extend_from_slice(b"\r\n");
}

#[inline(always)]
pub fn write_resp_bulk_bytesmut(out: &mut BytesMut, val: &[u8]) {
    let v_len = val.len();
    out.reserve(v_len + 16);
    out.extend_from_slice(b"$");
    match v_len {
        0 => out.extend_from_slice(b"0\r\n"),
        1..=9 => {
            out.extend_from_slice(&[b'0' + v_len as u8, b'\r', b'\n']);
        }
        10..=99 => {
            let p = v_len * 2;
            out.extend_from_slice(&[
                crate::shard::DIGIT_PAIRS[p],
                crate::shard::DIGIT_PAIRS[p + 1],
                b'\r',
                b'\n',
            ]);
        }
        100..=999 => {
            let h = (v_len / 100) as u8;
            let p = (v_len % 100) * 2;
            out.extend_from_slice(&[
                b'0' + h,
                crate::shard::DIGIT_PAIRS[p],
                crate::shard::DIGIT_PAIRS[p + 1],
                b'\r',
                b'\n',
            ]);
        }
        1000..=9999 => {
            let p1 = (v_len / 100) * 2;
            let p2 = (v_len % 100) * 2;
            out.extend_from_slice(&[
                crate::shard::DIGIT_PAIRS[p1],
                crate::shard::DIGIT_PAIRS[p1 + 1],
                crate::shard::DIGIT_PAIRS[p2],
                crate::shard::DIGIT_PAIRS[p2 + 1],
                b'\r',
                b'\n',
            ]);
        }
        _ => {
            let mut buf = [0u8; 20];
            let mut i = buf.len();
            let mut uval = v_len;
            while uval > 0 {
                i -= 1;
                buf[i] = b'0' + (uval % 10) as u8;
                uval /= 10;
            }
            out.extend_from_slice(&buf[i..]);
            out.extend_from_slice(b"\r\n");
        }
    }
    out.extend_from_slice(val);
    out.extend_from_slice(b"\r\n");
}

