            write_resp_bulk(out, b"LUA");
            if CURRENT_CLIENT_RESP3.get() {
                out.extend_from_slice(b"%2\r\n");
            } else {
                out.extend_from_slice(b"*4\r\n");
            }
            write_resp_bulk(out, b"libraries_count");
